procedure @@proc@@(p_id in number) is
  l_a varchar2(50);
  l_b varchar2(50);
begin
  begin
    select @@col@@ into l_a from @@tab@@ where id = p_id;
  exception
    when no_data_found then
      l_a := null;
  end;
  select @@col2@@ into l_b -- @expect
    from @@tab@@
   where id = p_id;
  dbms_output.put_line(l_a || l_b);
end @@proc@@;

procedure @@proc@@(p_ids in dbms_sql.number_table, p_kind in number) is
  l_v varchar2(50);
begin
  for i in 1 .. p_ids.count loop
    case p_kind
      when 3 then
        if p_ids(i) > 0 then
          select /* pick */ @@col@@ -- @expect
            /* target */ into l_v
            from @@tab@@
           where id = p_ids(i);
          dbms_output.put_line(l_v);
        end if;
      else
        null;
    end case;
  end loop;
exception
  when dup_val_on_index then
    null;
end @@proc@@;

function @@proc@@(p_status in varchar2) return number is
  l_sum number;
begin
  select sum(qty) into l_sum -- @expect
    from "Order Line" ol
   where ol.status = p_status
   group by ol.order_id;
  return l_sum;
end @@proc@@;

function @@proc@@(p_id in number) return varchar2 is
  l_v varchar2(100);
begin
  -- not a DUAL query, and no aggregate: 'from dual' is only text
  select 'count(*) from dual: ' || @@col@@ into l_v -- @expect
    from @@tab@@
   where id = p_id;
  return l_v;
end @@proc@@;

function @@proc@@(p_id in number) return number is
  function helper(p_x in number) return number is
    l_one number;
  begin
    select 7 into l_one from dual;
    return p_x + l_one;
  end helper;
  l_val number;
begin
  $IF $$use_view $THEN
  select qty into l_val -- @expect
    from "Order Line" where id = p_id;
  $ELSE
  l_val := p_id;
  $END
  return helper(l_val);
exception
  when value_error then
    return 0;
end @@proc@@;

