function @@proc@@(p_id in number) return varchar2 is
  l_v varchar2(100);
begin
  <<outer>>
  begin
    declare
      l_w varchar2(100);
    begin
      begin
        select @@col@@ into l_w from @@tab@@ where id = p_id;
        l_v := l_w;
      end;
    end;
  exception
    when no_data_found then
      l_v := null;
  end outer;
  return l_v;
end @@proc@@;

procedure @@proc@@(p_key in varchar2) is
  type t_ids is table of number;
  l_ids t_ids;
  l_txt varchar2(100) := 'select id into l_x from @@tab@@';
begin
  -- select id into l_one from @@tab@@ where @@col@@ = p_key;
  select id
    bulk
    collect into l_ids
    from @@tab@@
   where @@col@@ = p_key;
  dbms_output.put_line(l_ids.count || l_txt);
end @@proc@@;

function @@proc@@(p_status in varchar2) return number is
  l_c number;
  l_s number;
begin
  SELECT COUNT(*), SUM(ol.qty)
    INTO l_c, l_s
    FROM "Order Line" ol
   WHERE ol.status = p_status; /* not grouped: group by ol.order_id */
  return l_c + nvl(l_s, 0);
end @@proc@@;

function @@proc@@ return number is
  l_next number;
begin
	SELECT @@tab@@_seq.NEXTVAL
	  INTO l_next
	  FROM
	  DUAL;
  return l_next;
end @@proc@@;

procedure @@proc@@(p_keys in dbms_sql.number_table) is
  l_n varchar2(50);
begin
  for i in 1 .. p_keys.count loop
    begin
      select @@col@@ into l_n from @@tab@@ where id = p_keys(i);
      dbms_output.put_line(l_n);
    exception
      when no_data_found or too_many_rows then
        continue;
    end;
  end loop;
end @@proc@@;
